end;

procedure <Команда Тест прибора/>OnAfterRead(Device:TIGDevice; Command:TIGCommand; DriverData:TIGDriverData);
begin
 SetOtvResult(DriverData.result);
 if DriverData.result=0 then
  begin
   if DriverData.count>0 then
    if chr(DriverData[0])='Y' then
     ["Commands\Дополнительно\Тест прибора"].NewValue:=true
    else
     ["Commands\Дополнительно\Тест прибора"].NewValue:=false; 
  end
 else
  ["Commands\Дополнительно\Тест прибора"].NewQuality:=OPC_QUALITY_COMM_FAILURE;

end;

