procedure <Дата и время на счетчике/>OnWrite(Device:TIGDevice; Tags:TIGTags);
var ss,s,m,h,d,mo,y:word;
    str:string;
begin
 try
 DecodeDate(["Commands\Дополнительно\Дата и время на счетчике"].vqt.value,y,mo,d);
 DecodeTime(["Commands\Дополнительно\Дата и время на счетчике"].vqt.value,h,m,s,ss);

 str:=inttostr(2);
 ["Command_DataCurrWrite"][0]:=ord(str[1]);

 if d<=9 then
  str:='0'+inttostr(d)
 else
  str:=inttostr(d); 

 ["Command_DataCurrWrite"][1]:=ord(str[1]);
 ["Command_DataCurrWrite"][2]:=ord(str[2]);

 if mo<=9 then
  str:='0'+inttostr(mo)
 else
  str:=inttostr(mo); 

 ["Command_DataCurrWrite"][3]:=ord(str[1]);
 ["Command_DataCurrWrite"][4]:=ord(str[2]);

 y:=y-2000;
 if y<=9 then
  str:='0'+inttostr(y)
 else
  str:=inttostr(y); 

 ["Command_DataCurrWrite"][5]:=ord(str[1]);
 ["Command_DataCurrWrite"][6]:=ord(str[2]);

 ["Command_DataCurrWrite"].run;

 if h<=9 then
  str:='0'+inttostr(h)
 else
  str:=inttostr(h); 

 ["Command_TimeCurrWrite"][0]:=ord(str[1]);
 ["Command_TimeCurrWrite"][1]:=ord(str[2]);

 if m<=9 then
  str:='0'+inttostr(m)
 else
  str:=inttostr(m); 

 ["Command_TimeCurrWrite"][2]:=ord(str[1]);
 ["Command_TimeCurrWrite"][3]:=ord(str[2]);


 if s<=9 then
  str:='0'+inttostr(s)
 else
  str:=inttostr(s); 

 ["Command_TimeCurrWrite"][4]:=ord(str[1]);
 ["Command_TimeCurrWrite"][5]:=ord(str[2]);

 ["Command_TimeCurrWrite"].run;

 except
 end;

end;

procedure <Энергия по полупиковому тарифу за Январь/>OnRead(Device:TIGDevice; Tags:TIGTags; FromGroup:boolean);
var i,j:integer;
    s:string;
begin
 for i:=0 to Tags.count-1 do
  if Tags[i].PropExists(5000) then
   begin
     j:=Tags[i].Prop[5000].Value;
     if j<=9 then
      s:='0'+inttostr(j)
     else
      s:=inttostr(j);
     ["Command_["][0]:=ord(s[1]);
     ["Command_["][1]:=ord(s[2]);
     ["Command_["].run;
   end;
end;

procedure <Command_[/>OnAfterRead(Device:TIGDevice; Command:TIGCommand; DriverData:TIGDriverData);
var i,j:integer;
    s:string;
    d:dword;
begin
 SetOtvResult(DriverData.result);
 if Command.count=0 then exit;
 s:=chr(Command[0])+chr(Command[1]);
 j:=strtoint(s);
 for i:=0 to Device.Tags.count-1 do
  if Device.Tags[i].PropExists(5000) then
   if Device.Tags[i].Prop[5000].Value=j then
    begin
      if ExtractDWord(DriverData,d) then
        Device.Tags[i].NewValue:=d
      else
        Device.Tags[i].NewQuality:=OPC_QUALITY_COMM_FAILURE;
      break;   
    end;

end;

procedure <Command_T/>OnBeforeWrite(Device:TIGDevice; Command:TIGCommand; var Cancel:boolean);
begin
 ["Кол-во запросов"].NewValue:=["Кол-во запросов"].OldValue+1;

end;

procedure <Template/>OnActivateDevice(Device:TIGDevice);
begin
  ["Имя шаблона"].NewValue:=Device.TemplateName;
end;

procedure <Дата получаса/>OnWrite(Device:TIGDevice; Tags:TIGTags);


var d,mo,y:word;
    str:string;
    t,tx,cmin:double;
    dt:TDateTime;
begin
 cmin:=6.9444444444444444444444444444444e-4;
 try
  DecodeDate(["Commands\Получасовые нагрузки\Дата получаса"].vqt.value,y,mo,d);

  if mo<=9 then
   str:='0'+inttostr(mo)
  else
   str:=inttostr(mo);

  ["Command_?"][0]:=ord(str[1]);
  ["Command_?"][1]:=ord(str[2]);

  if d<=9 then
   str:='0'+inttostr(d)
  else
   str:=inttostr(d);

  ["Command_?"][2]:=ord(str[1]);
  ["Command_?"][3]:=ord(str[2]);

  dt:=["Commands\Получасовые нагрузки\Дата получаса"].vqt.value;
  ["Commands\Получасовые нагрузки\Дата получаса"].NewValue:=dt;
  t:=dt-round(dt);
  {tx:=1/24;
  tx:=tx/2;}
  tx:=0.020833333333333333333333333333333;
  t:=t/tx;  

  mo:=round(t);
  if mo<=9 then
   str:='0'+inttostr(mo)
  else
   str:=inttostr(mo);

  ["Command_?"][4]:=ord(str[1]);
  ["Command_?"][5]:=ord(str[2]);
  ["Command_?"].run;


 except
 end;



end;

procedure <Command_?/>OnAfterRead(Device:TIGDevice; Command:TIGCommand; DriverData:TIGDriverData);
var s:string;
    i,ii,j:integer;
    en:dword;
begin
 if Command.count=0 then exit;
 if DriverData.result<>0 then
  begin
   Command.run;
   exit;
  end; 
 s:=chr(Command[4])+chr(Command[5]);
 j:=strtoint(s);
 for i:=0 to Device.Tags.count-1 do
  if Device.Tags[i].PropExists(5002) then
   if Device.Tags[i].Prop[5002].Value=j then
    begin
     if DriverData.result=0 then
      begin
       try
        s:='';
        for ii:=1 to 4 do
         s:=s+chr(DriverData[ii]);
        en:=strtoint(s); 
        Device.Tags[i].NewValue:=en;
       except
         Device.Tags[i].NewQuality:=OPC_QUALITY_COMM_FAILURE;
       end;  
      end
     else
      Device.Tags[i].NewQuality:=OPC_QUALITY_COMM_FAILURE;
     break;  
    end;


end;

procedure <Дата суток/>OnWrite(Device:TIGDevice; Tags:TIGTags);
var c1sec,c30sec,t,nt:double;
    i:integer;
    d,mo,y:word;
    strmo,strd,str:string;
    dt:TDateTime;
begin
 c1sec:=6.9444444444444444444444444444444e-4;
 c30sec:=0.020833333333333333333333333333333;
 try
  dt:=["Commands\Посуточное потребление\Дата суток"].vqt.value;
  ["Commands\Посуточное потребление\Дата суток"].newValue:=dt;
  ["Commands\Посуточное потребление\Потребление за сутки"].newvalue:=0;
  DecodeDate(dt,y,mo,d);
  if mo<=9 then
   strmo:='0'+inttostr(mo)
  else
   strmo:=inttostr(mo);

  if d<=9 then
   strd:='0'+inttostr(d)
  else
   strd:=inttostr(d);

  t:=c1sec;        
  for i:=0 to 47 do
   begin

          ["Command_?1"][0]:=ord(strmo[1]);
          ["Command_?1"][1]:=ord(strmo[2]);
          ["Command_?1"][2]:=ord(strd[1]);
          ["Command_?1"][3]:=ord(strd[2]);


          nt:=t/c30sec;  
          mo:=round(nt);
          if mo<=9 then
           str:='0'+inttostr(mo)
          else
           str:=inttostr(mo);

          ["Command_?1"][4]:=ord(str[1]);
          ["Command_?1"][5]:=ord(str[2]);
          ["Command_?1"].run;

          t:=t+c30sec;
  end;

 except
 end;
end;

procedure <Command_?1/>OnAfterRead(Device:TIGDevice; Command:TIGCommand; DriverData:TIGDriverData);
var s:string;
    i:integer;
begin
 if DriverData.result=0 then
  begin
  if DriverData.count=6 then
   begin
     s:='';
     for i:=1 to 4 do
      s:=s+chr(DriverData[i]);
     try
      ["Commands\Посуточное потребление\Потребление за сутки"].newvalue:=
      ["Commands\Посуточное потребление\Потребление за сутки"].oldValue+strtoint(s);
     except
      ["Commands\Посуточное потребление\Потребление за сутки"].newQuality:=OPC_QUALITY_COMM_FAILURE;
     end;  
   end;
  end
 else
  ["Commands\Посуточное потребление\Потребление за сутки"].newQuality:=OPC_QUALITY_COMM_FAILURE;



end;

procedure <Нагрузка на 00:00/>OnRead(Device:TIGDevice; Tags:TIGTags; FromGroup:boolean);
var d,mo,y,no:word;
    str,strmo,strd:string;
    dt:TDateTime;
    i:integer;
begin
 if ["Commands\Получасовые нагрузки\Дата получаса"].OldQuality<>OPC_QUALITY_GOOD then exit;
 try

  dt:=["Commands\Получасовые нагрузки\Дата получаса"].OldValue;
  DecodeDate(dt,y,mo,d);

  if mo<=9 then
   strmo:='0'+inttostr(mo)
  else
   strmo:=inttostr(mo);

  if d<=9 then
   strd:='0'+inttostr(d)
  else
   strd:=inttostr(d);

  for i:=0 to Tags.count-1 do
  if Tags[i].PropExists(5002) then
   begin

          ["Command_?"][0]:=ord(strmo[1]);
          ["Command_?"][1]:=ord(strmo[2]);
          ["Command_?"][2]:=ord(strd[1]);
          ["Command_?"][3]:=ord(strd[2]);

          no:=Tags[i].Prop[5002].value;

          if no<=9 then
           str:='0'+inttostr(no)
          else
           str:=inttostr(no);

          ["Command_?"][4]:=ord(str[1]);
          ["Command_?"][5]:=ord(str[2]);
          ["Command_?"].run;


  end;



 except
 end;



end;

begin

end.
